/** Crea un ícono de 24x24 a partir de trazos SVG. */
private fun svgIcon(name: String, content: ImageVector.Builder.() -> Unit): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    ).apply(content).build()

/** Agrega un path con la sintaxis "d" de SVG (el color real lo pone el tint del Icon). */
private fun ImageVector.Builder.svgPath(
    pathData: String,
    stroked: Boolean,
    filled: Boolean,
    width: Float,
    cap: StrokeCap,
    join: StrokeJoin,
) {
    addPath(
        pathData = addPathNodes(pathData),
        fill = if (filled) SolidColor(Color.Black) else null,
        stroke = if (stroked) SolidColor(Color.Black) else null,
        strokeLineWidth = width,
        strokeLineCap = cap,
        strokeLineJoin = join,
    )
}
